2	
3	/* Prelude's components: built from tokens.css and nothing else. Each class
4	   has its canonical markup in components/<name>.html. Layout inside a
5	   component answers to its container, never to the window: a component may
6	   sit in a page, a chat column or a pop-out window. */
7	
8	/* ------------------------------------------------------------------ base */
9	
10	@layer base {
11	  *, *::before, *::after { box-sizing: border-box; }
12	  html { -webkit-text-size-adjust: 100%; }
13	  html, body { margin: 0; padding: 0; }
14	  body {
15	    background: var(--bg);
16	    color: var(--fg);
17	    font: var(--weight-normal) var(--text-base)/var(--leading) var(--font-sans);
18	    -webkit-font-smoothing: antialiased;
19	  }
20	  [hidden] { display: none !important; }
21	
22	  /* Blocks carry no outer margin: the space between them is the gap of the
23	     layout primitive they sit in (.stack, .cluster…). .prose is the one
24	     exception, for rendered markdown that can't be wrapped. */
25	  h1, h2, h3, h4, p, ul, ol, dl, dd, figure, blockquote, hr { margin: 0; }
26	  h1 { font-size: var(--text-2xl); line-height: var(--leading-tight); letter-spacing: -0.02em; font-weight: var(--weight-heading); }
27	  h2, h3, h4 { letter-spacing: -0.01em; font-weight: var(--weight-strong); }
28	  strong { font-weight: var(--weight-strong); }
29	
30	  a { color: var(--accent); text-underline-offset: 0.18em; }
31	  a:hover { color: var(--accent-hover); }
32	  :focus-visible { outline: none; box-shadow: var(--ring); border-radius: var(--radius-sm); }
33	
