1	/* The gallery's own rules: how the specimens look. Unlayered, like any
2	   design's. Built from the tokens only; all spacing between blocks comes from
3	   the system's layout primitives in the markup. */
4	
5	/* Light, dark, or the system's: a choice in the header, no script */
6	:root:has(#scheme-light:checked) { color-scheme: light; }
7	:root:has(#scheme-dark:checked) { color-scheme: dark; }
8	
9	.gallery { --measure-now: 60rem; padding-block: var(--space-8); }
10	.gallery-intro { max-width: var(--measure); }
11	.scheme { font-size: var(--text-sm); color: var(--fg-muted); }
12	.scheme label { display: inline-flex; gap: var(--space-1); align-items: center; }
13	
14	.specimen > h3 { font-size: var(--text-md); }
15	.specimen + .specimen { padding-top: var(--space-5); border-top: var(--border-width) solid var(--border); }
16	.stage { padding: var(--space-4); background: var(--bg); border: var(--border-width) dashed var(--border); border-radius: var(--radius-md); }
17	.stage.tall { height: 22rem; display: flex; padding: 0; overflow: hidden; }
18	.stage.tall > .panel { flex: 1; border: 0; border-radius: 0; }
19	.stage.session { height: 34rem; }
20	.stage > .menu-list { inline-size: fit-content; }
21	.stage dialog { position: static; }
22	
23	/* A stand-in block, to show what a layout primitive does with its children */
24	.demo { padding: var(--space-2) var(--space-3); background: var(--accent-soft); border: var(--border-width) solid var(--accent); border-radius: var(--radius-sm); font-size: var(--text-sm); }
25	.demo.tall { min-block-size: 6rem; }
26	.stage.resizable { resize: horizontal; overflow: auto; max-inline-size: 100%; }
27	
28	/* Tokens */
29	.swatch { font-size: var(--text-xs); }
30	.swatch code { align-self: flex-start; }
31	.swatch-chip { display: block; height: var(--control-lg); border-radius: var(--radius-md); background: var(--swatch); border: var(--border-width) solid var(--border); }
32	.scale-row > :first-child { flex: none; inline-size: 9rem; }

